1	// Switchboard's web page: pair a browser from the pairing window's QR,
2	// list the sessions with the waiting ones first, read one, and reply.
3	// It speaks the remote port's /api/v1 as a native client does, with
4	// two differences: the token is a cookie this script never sees, and
5	// changes arrive by polling, the events socket only hastening them.
6	// Text from the host is set with textContent only, never as markup.
7	'use strict';
8	
9	// Every route the page calls, method and path. A host test reads this
10	// table and checks that each one is served.
11	const API = {
12	  info: 'GET /api/v1/info',
13	  pair: 'POST /api/v1/pair',
14	  me: 'GET /api/v1/me',
15	  projects: 'GET /api/v1/projects',
16	  sessions: 'GET /api/v1/projects/{id}/sessions',
17	  waiting: 'GET /api/v1/waiting',
18	  lastResponse: 'GET /api/v1/sessions/{id}/last-response',
19	  screen: 'GET /api/v1/sessions/{id}/screen',
20	  send: 'POST /api/v1/sessions/{id}/send',
21	  events: 'GET /api/v1/events',
22	};
23	
24	const STORE_KEY = 'switchboard-host';
25	const POLL_FAST_MS = 3000;
26	const POLL_SLOW_MS = 20000;
27	const SOCKET_RETRY_MS = 5000;
28	const SOCKET_RETRY_MAX_MS = 60000;
29	
30	// --- pure parts, tested with node --test
31	
32	/** The invite in a URL fragment, `#code=…&key=…&id=…`, or null. */
33	function parseFragment(hash) {
34	  const text = (hash || '').replace(/^#/, '');
35	  const fields = {};
36	  for (const pair of text.split('&')) {
37	    const at = pair.indexOf('=');
38	    if (at <= 0) continue;
39	    try {
40	      fields[pair.slice(0, at)] = decodeURIComponent(pair.slice(at + 1));
41	    } catch (_) {
42	      return null;
43	    }
44	  }
45	  if (!fields.code || !fields.key || !fields.id) return null;
46	  return { code: fields.code, key: fields.key.toLowerCase(), id: fields.id.toLowerCase() };
47	}
48	
49	/** "Safari on iPhone", from the user agent; the host shows it. */
50	function deviceName(ua, touchPoints) {
51	  ua = ua || '';
52	  let browser = 'Safari';
53	  if (/Edg\//.test(ua)) browser = 'Edge';
54	  else if (/Chrome\/|CriOS\//.test(ua)) browser = 'Chrome';
55	  else if (/Firefox\/|FxiOS\//.test(ua)) browser = 'Firefox';
56	  else if (!/Safari\//.test(ua)) return 'Browser';
57	  let device = null;
58	  if (/iPhone/.test(ua)) device = 'iPhone';
59	  else if (/iPad/.test(ua) || (/Macintosh/.test(ua) && touchPoints > 1)) device = 'iPad';
60	  else if (/Android/.test(ua)) device = 'Android';
61	  else if (/Macintosh|Mac OS X/.test(ua)) device = 'Mac';
62	  else if (/Windows/.test(ua)) device = 'Windows';
63	  else if (/Linux/.test(ua)) device = 'Linux';
64	  return device ? `${browser} on ${device}` : 'Browser';
65	}
66	
67	/**
68	 * What a 401 means, told from `/info`, which answers anyone: the host
69	 * this page paired with, under the same key, no longer knows the device
70	 * ("removed"); a different key or id ("changed"); no answer
71	 * ("unreachable"); or nothing was ever paired here ("unpaired").
72	 */
73	function inferUnauthorized(stored, info) {
74	  if (!stored) return 'unpaired';
75	  if (!info) return 'unreachable';
76	  const same = String(info.server_id).toLowerCase() === stored.server_id
77	    && String(info.spki_sha256).toLowerCase() === stored.spki_sha256;
78	  return same ? 'removed' : 'changed';
79	}
80	
81	/**
82	 * Whether a reply at `next` may replace what is held at `held`: a
83	 * restarted host (a new epoch) always may; otherwise only a revision at
84	 * or past the held one, so a late reply never undoes a newer one.
85	 */
86	function isCurrent(held, next) {
87	  if (!held) return true;
88	  if (held.epoch !== next.epoch) return true;
89	  return next.revision >= held.revision;
90	}
91	
92	/**
93	 * The projects with their sessions, a project with a waiting session
94	 * first and waiting sessions first within each, the host's order kept
95	 * otherwise. Projects with no session are left out.
96	 */
97	function orderSessions(projects, sessionsByProject) {
98	  const waitingFirst = (list) => list
99	    .map((item, i) => ({ item, i }))
100	    .sort((a, b) => (b.item.waiting - a.item.waiting) || (a.i - b.i))
101	    .map((x) => x.item);
102	  const groups = projects
103	    .map((project) => ({
104	      project,
105	      sessions: waitingFirst((sessionsByProject[project.id] || []).map((s) => ({ ...s, waiting: !!s.waiting }))),
106	    }))
107	    .filter((g) => g.sessions.length > 0)
108	    .map((g) => ({ ...g, waiting: g.sessions.some((s) => s.waiting) }));
109	  return waitingFirst(groups).map(({ project, sessions }) => ({ project, sessions }));
110	}
111	
112	/** "just now", "5 min ago", "3 h ago", "2 d ago". */
113	function sinceText(ms, now) {
114	  if (ms == null) return '';
115	  const secs = Math.max(0, Math.floor((now - ms) / 1000));
116	  if (secs < 60) return 'just now';
117	  if (secs < 3600) return `${Math.floor(secs / 60)} min ago`;
118	  if (secs < 86400) return `${Math.floor(secs / 3600)} h ago`;
119	  return `${Math.floor(secs / 86400)} d ago`;
120	}
121	
122	/** A route from the table with its `{id}` filled. */
123	function route(entry, id) {
124	  const [method, path] = entry.split(' ');
125	  return { method, path: path.replace('{id}', encodeURIComponent(id || '')) };
126	}
127	
128	if (typeof module !== 'undefined' && module.exports) {
129	  module.exports = { API, parseFragment, deviceName, inferUnauthorized, isCurrent, orderSessions, sinceText, route };
130	}
131	
132	// --- the page
133	
134	if (typeof document !== 'undefined') {
135	  const $ = (id) => document.getElementById(id);
136	  const state = {
137	    me: null,
138	    listMark: null,
139	    open: null,
140	    held: {},
141	    pending: null,
142	    socket: null,
143	    socketRetry: SOCKET_RETRY_MS,
144	    pollMs: POLL_FAST_MS,
145	    timer: null,
146	  };
147	
148	  class HttpError extends Error {
149	    constructor(status, code, message) {
150	      super(message || code);
151	      this.status = status;
152	      this.code = code;
153	    }
154	  }
155	
156	  async function call(entry, id, body) {
157	    const { method, path } = route(entry, id);
158	    const init = { method, credentials: 'same-origin', cache: 'no-store', headers: {} };
159	    if (body !== undefined) {
160	      init.headers['Content-Type'] = 'application/json';
161	      init.body = JSON.stringify(body);
162	    }
163	    const response = await fetch(path, init);
164	    let json = null;
165	    try { json = await response.json(); } catch (_) { json = null; }
166	    if (!response.ok) {
167	      const error = (json && json.error) || {};
168	      throw new HttpError(response.status, error.code || 'failed', error.message);
169	    }
170	    return json;
171	  }
172	
173	  function stored() {
174	    try { return JSON.parse(localStorage.getItem(STORE_KEY)); } catch (_) { return null; }
175	  }
176	
177	  function show(section) {
178	    for (const id of ['notice', 'list', 'session']) $(id).hidden = id !== section;
179	    $('header').hidden = section === 'notice' || !state.me;
180	  }
181	
182	  function notice(title, text) {
183	    $('notice-title').textContent = title;
184	    $('notice-text').textContent = text;
185	    show('notice');
186	  }
187	
188	  const NOTICES = {
189	    unpaired: ['Not paired', 'Open Remote devices on the Mac, allow pairing, and scan its code with this phone.'],
190	    removed: ['This device was removed on the host', 'Pair again from the Mac’s Remote devices window.'],
191	    changed: ['Identity changed', 'The host at this address is not the one this browser paired with. Pair again.'],
192	    unreachable: ['Can’t reach the host', 'Check that the Mac is awake, Switchboard is running, and it allows devices on the local network.'],
193	    cookieRefused: ['Paired, but this browser did not keep the sign-in', 'The Mac lists this device; remove it there. This browser refused the host’s cookie, so try another browser.'],
194	  };
195	
196	  const PAIR_ERRORS = {
197	    pairing_closed: 'Pairing is not open on the Mac. Open it again and scan the new code.',
198	    wrong_code: 'The code did not match. Scan the code the Mac shows now.',
199	    wrong_key: 'The host refused the key. Scan the code again on the Mac you mean.',
200	    rate_limited: 'Too many attempts. Wait a minute and scan again.',
201	  };
202	
203	  async function unauthorized() {
204	    stopUpdates();
205	    const saved = stored();
206	    let info = null;
207	    if (saved) {
208	      try { info = (await call(API.info)).body; } catch (_) { info = null; }
209	    }
210	    const [title, text] = NOTICES[inferUnauthorized(saved, info)];
211	    state.me = null;
212	    notice(title, text);
213	  }
214	
215	  /**
216	   * A failed request: a 401 says why; no answer says so until a later
217	   * poll succeeds; any other error says so only before the list was
218	   * ever drawn, since otherwise the page would be left blank.
219	   */
220	  async function failed(error) {
221	    if (error instanceof HttpError && error.status === 401) return unauthorized();
222	    if (!(error instanceof HttpError)) return notice(...NOTICES.unreachable);
223	    if (!state.listMark) return notice('The host answered with an error', `${error.message}. Reload to try again.`);
224	    return null;
225	  }
226	
227	  /** The section the signed-in page is on: the open session or the list. */
228	  function showCurrent() {
229	    show(state.open ? 'session' : 'list');
230	  }
231	
232	  async function pair(invite) {
233	    let info;
234	    try { info = (await call(API.info)).body; } catch (_) { return notice(...NOTICES.unreachable); }
235	    if (String(info.spki_sha256).toLowerCase() !== invite.key || String(info.server_id).toLowerCase() !== invite.id) {
236	      return notice('Wrong host', 'This address is a different Switchboard than the code was for. Nothing was sent.');
237	    }
238	    try {
239	      await call(API.pair, null, {
240	        code: invite.code,
241	        spki_sha256: invite.key,
242	        device_name: deviceName(navigator.userAgent, navigator.maxTouchPoints || 0),
243	        transport: 'cookie',
244	      });
245	    } catch (error) {
246	      if (error instanceof HttpError) return notice('Pairing failed', PAIR_ERRORS[error.code] || error.message);
247	      return notice(...NOTICES.unreachable);
248	    }
249	    // The host is remembered only once the cookie is shown to work: a
250	    // browser that refused it would otherwise read its next 401 as this
251	    // device removed on the host.
252	    try {
253	      state.me = (await call(API.me)).body;
254	    } catch (error) {
255	      if (error instanceof HttpError && error.status === 401) return notice(...NOTICES.cookieRefused);
256	      return failed(error);
257	    }
258	    localStorage.setItem(STORE_KEY, JSON.stringify({
259	      server_id: invite.id,
260	      spki_sha256: invite.key,
261	      server_name: info.server_name,
262	    }));
263	    return enter();
264	  }
265	
266	  async function start() {
267	    try {
268	      state.me = (await call(API.me)).body;
269	    } catch (error) {
270	      return failed(error);
271	    }
272	    return enter();
273	  }
274	
275	  /** Draw the signed-in page for `state.me` and keep it current. */
276	  async function enter() {
277	    $('host-name').textContent = state.me.server_name || 'Switchboard';
278	    $('scope').textContent = state.me.scope;
279	    await refreshList();
280	    startUpdates();
281	    return null;
282	  }
283	
284	  async function refreshList() {
285	    let projects;
286	    const sessionsByProject = {};
287	    let mark;
288	    try {
289	      const reply = await call(API.projects);
290	      mark = { epoch: reply.epoch, revision: reply.revision };
291	      projects = reply.body.projects || [];
292	      // One at a time, on the one kept connection: requests in
293	      // parallel would open new connections, and the host holds four
294	      // that have not yet authenticated before it refuses a fifth.
295	      for (const p of projects) {
296	        const r = await call(API.sessions, p.id);
297	        sessionsByProject[p.id] = r.body.sessions || [];
298	      }
299	    } catch (error) {
300	      return failed(error);
301	    }
302	    if (!isCurrent(state.listMark, mark)) return null;
303	    state.listMark = mark;
304	    state.sessions = {};
305	    for (const list of Object.values(sessionsByProject)) {
306	      for (const s of list) state.sessions[s.id] = s;
307	    }
308	    drawList(orderSessions(projects, sessionsByProject));
309	    if (state.open) {
310	      if (state.sessions[state.open]) await refreshSession();
311	      else closeSession();
312	    }
313	    return null;
314	  }
315	
316	  function drawList(groups) {
317	    const root = $('projects');
318	    root.replaceChildren();
319	    $('list-empty').hidden = groups.length > 0;
320	    const now = Date.now();
321	    for (const { project, sessions } of groups) {
322	      const heading = document.createElement('h3');
323	      heading.textContent = project.name;
324	      root.append(heading);
325	      for (const s of sessions) {
326	        const row = document.createElement('button');
327	        row.type = 'button';
328	        row.className = s.waiting ? 'row is-waiting' : 'row';
329	        if (s.waiting) {
330	          const w = document.createElement('p');
331	          w.className = 'waiting';
332	          w.textContent = s.waiting_reason ? `Waiting on you: ${s.waiting_reason}` : 'Waiting on you';
333	          row.append(w);
334	        }
335	        const name = document.createElement('div');
336	        name.className = 'name';
337	        name.textContent = s.name;
338	        const meta = document.createElement('div');
339	        meta.className = 'meta';
340	        meta.textContent = [s.kind, s.card, sinceText(s.last_activity_ms, now)].filter(Boolean).join(' · ');
341	        row.append(name, meta);
342	        row.addEventListener('click', () => openSession(s.id));
343	        root.append(row);
344	      }
345	    }
346	    showCurrent();
347	  }
348	
349	  function openSession(id) {
350	    if (state.open !== id) {
351	      $('reply-text').value = '';
352	      $('reply-status').textContent = '';
353	      $('session-text').textContent = '';
354	      state.pending = null;
355	    }
356	    state.open = id;
357	    show('session');
358	    refreshSession();
359	  }
360	
361	  function closeSession() {
362	    state.open = null;
363	    show('list');
364	  }
365	
366	  async function refreshSession() {
367	    const id = state.open;
368	    const s = state.sessions && state.sessions[id];
369	    if (!s) return null;
370	    $('session-name').textContent = s.name;
371	    $('session-meta').textContent = [s.kind, s.card, sinceText(s.last_activity_ms, Date.now())].filter(Boolean).join(' · ');
372	    $('session-waiting').hidden = !s.waiting;
373	    $('session-waiting').textContent = s.waiting_reason ? `Waiting on you: ${s.waiting_reason}` : 'Waiting on you';
374	    const canReply = state.me && state.me.scope === 'control';
375	    $('reply').hidden = !canReply || s.prompt_refusal != null;
376	    $('session-refusal').hidden = !canReply || s.prompt_refusal == null;
377	    $('session-refusal').textContent = s.prompt_refusal ? `No reply from here: ${s.prompt_refusal}` : '';
378	    const entry = s.kind === 'claude' ? API.lastResponse : API.screen;
379	    const key = `${entry} ${id}`;
380	    try {
381	      const reply = await call(entry, id);
382	      if (state.open !== id || !isCurrent(state.held[key], reply)) return null;
383	      state.held[key] = { epoch: reply.epoch, revision: reply.revision };
384	      $('session-text').textContent = reply.body.text || '';
385	    } catch (error) {
386	      if (error instanceof HttpError && error.status !== 401) {
387	        if (state.open === id) $('session-text').textContent = error.message;
388	        return null;
389	      }
390	      return failed(error);
391	    }
392	    return null;
393	  }
394	
395	  function newOp() {
396	    const bytes = new Uint8Array(16);
397	    crypto.getRandomValues(bytes);
398	    return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
399	  }
400	
401	  async function send() {
402	    const id = state.open;
403	    const text = $('reply-text').value.trim();
404	    if (!id || !text) return null;
405	    // The same text to the same session keeps its op, so a retry after
406	    // a lost reply is answered from the host's log, not typed twice.
407	    if (!state.pending || state.pending.session !== id || state.pending.text !== text) {
408	      state.pending = { session: id, text, op: newOp() };
409	    }
410	    $('send').disabled = true;
411	    $('reply-status').textContent = 'Sending…';
412	    try {
413	      await call(API.send, id, { op: state.pending.op, text });
414	      state.pending = null;
415	      $('reply-text').value = '';
416	      $('reply-status').textContent = 'Sent.';
417	    } catch (error) {
418	      if (error instanceof HttpError && error.status === 403 && error.code === 'scope') {
419	        $('reply-status').textContent = 'This device reads only.';
420	        try { state.me = (await call(API.me)).body; $('scope').textContent = state.me.scope; } catch (_) { /* the next poll says */ }
421	        await refreshSession();
422	      } else if (error instanceof HttpError && error.status === 401) {
423	        await unauthorized();
424	      } else if (error instanceof HttpError) {
425	        $('reply-status').textContent = error.message;
426	      } else {
427	        $('reply-status').textContent = 'Not sure it went. Send again: it will not be typed twice.';
428	      }
429	    } finally {
430	      $('send').disabled = false;
431	    }
432	    return null;
433	  }
434	
435	  // --- updates: a poll, hastened by the events socket when it connects
436	
437	  async function poll() {
438	    state.timer = null;
439	    if (document.visibilityState === 'visible' && state.me) {
440	      try {
441	        const reply = await call(API.waiting);
442	        const mark = state.listMark;
443	        if (!mark || mark.epoch !== reply.epoch || mark.revision !== reply.revision) {
444	          await refreshList();
445	        } else {
446	          // Nothing changed, but an earlier failed poll may have put up
447	          // "Can't reach the host"; the answer just now takes it down.
448	          showCurrent();
449	        }
450	      } catch (error) {
451	        await failed(error);
452	      }
453	    }
454	    if (state.me) schedule();
455	  }
456	
457	  function schedule() {
458	    if (state.timer) clearTimeout(state.timer);
459	    state.timer = setTimeout(poll, state.pollMs);
460	  }
461	
462	  function startUpdates() {
463	    state.pollMs = POLL_FAST_MS;
464	    schedule();
465	    openSocket();
466	  }
467	
468	  function stopUpdates() {
469	    if (state.timer) clearTimeout(state.timer);
470	    state.timer = null;
471	    if (state.socket) {
472	      state.socket.onclose = null;
473	      state.socket.close();
474	      state.socket = null;
475	    }
476	  }
477	
478	  function openSocket() {
479	    if (!state.me || state.socket) return;
480	    let socket;
481	    try {
482	      socket = new WebSocket(`wss://${location.host}${route(API.events).path}`);
483	    } catch (_) {
484	      return;
485	    }
486	    state.socket = socket;
487	    socket.onopen = () => {
488	      state.socketRetry = SOCKET_RETRY_MS;
489	      state.pollMs = POLL_SLOW_MS;
490	      schedule();
491	    };
492	    socket.onmessage = (event) => {
493	      let frame;
494	      try { frame = JSON.parse(event.data); } catch (_) { return; }
495	      if (frame.type === 'changed' || frame.type === 'removed' || frame.type === 'resync_required') {
496	        refreshList();
497	      }
498	    };
499	    socket.onclose = () => {
500	      state.socket = null;
501	      state.pollMs = POLL_FAST_MS;
502	      refreshList();
503	      schedule();
504	      const wait = state.socketRetry;
505	      state.socketRetry = Math.min(state.socketRetry * 2, SOCKET_RETRY_MAX_MS);
506	      setTimeout(openSocket, wait);
507	    };
508	  }
509	
510	  document.addEventListener('visibilitychange', () => {
511	    if (document.visibilityState === 'visible' && state.me) poll();
512	  });
513	
514	  document.addEventListener('DOMContentLoaded', () => {
515	    $('back').addEventListener('click', closeSession);
516	    $('send').addEventListener('click', send);
517	    const invite = parseFragment(location.hash);
518	    // The code leaves the address bar before anything else happens.
519	    if (location.hash) history.replaceState(null, '', location.pathname);
520	    if (invite) pair(invite);
521	    else start();
522	  });
523	}
